function switchAppMode(mode) {
  currentMode = mode;
  const parentView = document.getElementById('parent-view');
  const adminView = document.getElementById('admin-view');
  const btnParent = document.getElementById('btn-mode-parent');
  const btnAdmin = document.getElementById('btn-mode-admin');

  if (mode === 'parent') {
    parentView.classList.remove('hidden');
    adminView.classList.add('hidden');
    btnParent.className = 'mode-pill-active flex items-center gap-1 px-2.5 py-1.5 rounded-full text-xs transition cursor-pointer whitespace-nowrap';
    btnAdmin.className = 'mode-pill-inactive relative flex items-center gap-1 px-2.5 py-1.5 rounded-full text-xs transition cursor-pointer whitespace-nowrap';
  } else {
    parentView.classList.add('hidden');
    adminView.classList.remove('hidden');
    btnAdmin.className = 'mode-pill-active relative flex items-center gap-1 px-2.5 py-1.5 rounded-full text-xs transition cursor-pointer whitespace-nowrap';
    btnParent.className = 'mode-pill-inactive flex items-center gap-1 px-2.5 py-1.5 rounded-full text-xs transition cursor-pointer whitespace-nowrap';

    checkAdminAuthStatus();
  }
  lucide.createIcons();
}

function checkAdminAuthStatus() {
  const isAuth = isAdminAuthenticated();
  const loginBox = document.getElementById('admin-login-box');
  const workspace = document.getElementById('admin-workspace');

  if (isAuth) {
    loginBox.classList.add('hidden');
    workspace.classList.remove('hidden');
    refreshAllViews();
  } else {
    loginBox.classList.remove('hidden');
    workspace.classList.add('hidden');
  }
}

function handleAdminLogin(e) {
  e.preventDefault();
  const inputPass = document.getElementById('admin-password-input').value.trim();
  const actualPass = isSandboxDraftMode
    ? String(appState.settings.sandboxAdminPassword || 'DEMO-NHAP-2026').trim()
    : String(appState.settings.adminPassword || '123456').trim();

  if (inputPass === actualPass) {
    const authKey = isSandboxDraftMode ? STORAGE_KEYS.SANDBOX_AUTH : STORAGE_KEYS.ADMIN_AUTH;
    sessionStorage.setItem(authKey, 'true');
    document.getElementById('admin-password-input').value = '';
    showToast(
      isSandboxDraftMode ? 'Đăng nhập Quản lý (Bản Nháp) thành công!' : 'Đăng nhập Quản lý chính thành công!',
      'success'
    );
    checkAdminAuthStatus();
  } else {
    showToast('Mật khẩu quản trị không đúng!', 'error');
  }
}

function handleAdminLogout() {
  const authKey = isSandboxDraftMode ? STORAGE_KEYS.SANDBOX_AUTH : STORAGE_KEYS.ADMIN_AUTH;
  sessionStorage.removeItem(authKey);
  showToast('Đã đăng xuất khỏi phiên Quản lý.', 'info');
  checkAdminAuthStatus();
}

