              const st = Number(states[cell.dateKey] || 0);
              const prefix = st === 1 ? '✓ ' : st === 2 ? '★ ' : st === 3 ? '✕ ' : '';
              return `<td style="width: ${colWidthPct}" class="py-2.5 px-1.5 session-state-${st} text-xs sm:text-sm h-[40px] font-semibold">${prefix}${cell.label}</td>`;
