                            <span class="px-3.5 py-1.5 rounded-xl bg-amber-400 text-slate-950 font-black text-sm sm:text-base uppercase tracking-wider shrink-0 shadow-sm">
                              ${escapeHtml(hist.batchLabel)}
                            </span>
